# Get all comprehensive drugs
def get_all_comprehensive_drugs():
    """Return all comprehensive drug data with timestamps"""
    all_drugs = []
    all_drugs.extend(CARDIOVASCULAR_DRUGS)
    all_drugs.extend(RESPIRATORY_DRUGS)
    
    # Add timestamps
    timestamp = get_timestamp()
    for drug in all_drugs:
        drug["created_at"] = timestamp
        drug["updated_at"] = timestamp
    
    return all_drugs
